using System;
using UnityEngine;

[DisallowMultipleComponent]
public class MoveToTarget : MonoBehaviour
{
    private const float ArrivalThresholdSqr = 0.0000001f;

    [SerializeField, Min(0f)] private float speed = 5f;

    private Vector3 _targetPosition;
    private bool _hasTarget;
    private bool _hasArrived;

    public event Action OnArrived;

    public bool HasArrived => _hasArrived;
    public bool HasTarget => _hasTarget;

    public void SetTarget(Vector3 targetPosition)
    {
        _targetPosition = targetPosition;
        _hasTarget = true;
        _hasArrived = false;
    }

    private void Update()
    {
        Tick(Time.deltaTime);
    }

    public void Tick(float deltaTime)
    {
        if (!_hasTarget || _hasArrived)
        {
            return;
        }

        float maxDistanceDelta = speed * deltaTime;
        transform.position = Vector3.MoveTowards(transform.position, _targetPosition, maxDistanceDelta);

        if ((transform.position - _targetPosition).sqrMagnitude <= ArrivalThresholdSqr)
        {
            _hasArrived = true;
            OnArrived?.Invoke();
        }
    }
}
