using System.Collections;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;

public class MoveToTargetTests
{
    [Test]
    public void Tick_Arrives_Exactly_Without_Overshoot()
    {
        var go = new GameObject();
        var mover = go.AddComponent<MoveToTarget>();
        mover.SetTarget(new Vector3(10f, 0f, 0f));

        mover.Tick(100f);

        Assert.AreEqual(new Vector3(10f, 0f, 0f), go.transform.position);
        Assert.IsTrue(mover.HasArrived);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void OnArrived_Event_Fires_Exactly_Once()
    {
        var go = new GameObject();
        var mover = go.AddComponent<MoveToTarget>();
        mover.SetTarget(new Vector3(5f, 0f, 0f));

        int firedCount = 0;
        mover.OnArrived += () => firedCount++;

        mover.Tick(100f);
        mover.Tick(100f);

        Assert.AreEqual(1, firedCount);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void No_Target_Does_Not_Move_Or_Arrive()
    {
        var go = new GameObject();
        go.transform.position = new Vector3(2f, 2f, 2f);
        var mover = go.AddComponent<MoveToTarget>();

        mover.Tick(1f);

        Assert.AreEqual(new Vector3(2f, 2f, 2f), go.transform.position);
        Assert.IsFalse(mover.HasArrived);

        Object.DestroyImmediate(go);
    }

    [Test]
    public void SetTarget_Resets_Arrived_Flag()
    {
        var go = new GameObject();
        var mover = go.AddComponent<MoveToTarget>();
        mover.SetTarget(new Vector3(1f, 0f, 0f));
        mover.Tick(100f);
        Assert.IsTrue(mover.HasArrived);

        mover.SetTarget(new Vector3(3f, 0f, 0f));

        Assert.IsFalse(mover.HasArrived);

        Object.DestroyImmediate(go);
    }

    [UnityTest]
    public IEnumerator Reaches_Target_Over_Multiple_Frames()
    {
        var go = new GameObject();
        go.transform.position = Vector3.zero;
        var mover = go.AddComponent<MoveToTarget>();
        mover.SetTarget(new Vector3(1f, 0f, 0f));

        bool arrived = false;
        mover.OnArrived += () => arrived = true;

        for (int i = 0; i < 60 && !arrived; i++)
        {
            yield return null;
        }

        Assert.IsTrue(arrived);
        Assert.AreEqual(new Vector3(1f, 0f, 0f), go.transform.position);

        Object.Destroy(go);
    }
}
